package jdk.internal.reflect;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import jdk.internal.misc.Unsafe;

/** monolith: Field get/set through Unsafe offsets (GENERATED by tools — see MethodHandleAccessorFactory). */
final class MonoFieldAccessor extends FieldAccessorImpl {
    private static final Unsafe U = Unsafe.getUnsafe();
    private final boolean isStatic, readOnly, isVolatile;
    private final long offset;
    private final Class<?> type;

    MonoFieldAccessor(Field f, boolean readOnly) {
        super(f);
        int mod = f.getModifiers();
        this.isStatic = Modifier.isStatic(mod);
        this.readOnly = readOnly;
        this.isVolatile = Modifier.isVolatile(mod);
        this.type = f.getType();
        if (isStatic) {
            U.ensureClassInitialized(f.getDeclaringClass());
            this.offset = U.staticFieldOffset(f);
        } else {
            this.offset = U.objectFieldOffset(f);
        }
    }

    private Object base(Object obj) {
        if (isStatic) return null;
        ensureObj(obj);
        return obj;
    }

    private void checkWrite() throws IllegalAccessException {
        if (readOnly) throw new IllegalAccessException("Can not set final field " + getQualifiedFieldName());
    }

    private Object rRef(Object b) { return isVolatile ? U.getReferenceVolatile(b, offset) : U.getReference(b, offset); }
    private boolean rBool(Object b) { return isVolatile ? U.getBooleanVolatile(b, offset) : U.getBoolean(b, offset); }
    private byte rByte(Object b) { return isVolatile ? U.getByteVolatile(b, offset) : U.getByte(b, offset); }
    private char rChar(Object b) { return isVolatile ? U.getCharVolatile(b, offset) : U.getChar(b, offset); }
    private short rShort(Object b) { return isVolatile ? U.getShortVolatile(b, offset) : U.getShort(b, offset); }
    private int rInt(Object b) { return isVolatile ? U.getIntVolatile(b, offset) : U.getInt(b, offset); }
    private long rLong(Object b) { return isVolatile ? U.getLongVolatile(b, offset) : U.getLong(b, offset); }
    private float rFloat(Object b) { return isVolatile ? U.getFloatVolatile(b, offset) : U.getFloat(b, offset); }
    private double rDouble(Object b) { return isVolatile ? U.getDoubleVolatile(b, offset) : U.getDouble(b, offset); }

    private void wRef(Object b, Object v) { if (isVolatile) U.putReferenceVolatile(b, offset, v); else U.putReference(b, offset, v); }
    private void wBool(Object b, boolean v) { if (isVolatile) U.putBooleanVolatile(b, offset, v); else U.putBoolean(b, offset, v); }
    private void wByte(Object b, byte v) { if (isVolatile) U.putByteVolatile(b, offset, v); else U.putByte(b, offset, v); }
    private void wChar(Object b, char v) { if (isVolatile) U.putCharVolatile(b, offset, v); else U.putChar(b, offset, v); }
    private void wShort(Object b, short v) { if (isVolatile) U.putShortVolatile(b, offset, v); else U.putShort(b, offset, v); }
    private void wInt(Object b, int v) { if (isVolatile) U.putIntVolatile(b, offset, v); else U.putInt(b, offset, v); }
    private void wLong(Object b, long v) { if (isVolatile) U.putLongVolatile(b, offset, v); else U.putLong(b, offset, v); }
    private void wFloat(Object b, float v) { if (isVolatile) U.putFloatVolatile(b, offset, v); else U.putFloat(b, offset, v); }
    private void wDouble(Object b, double v) { if (isVolatile) U.putDoubleVolatile(b, offset, v); else U.putDouble(b, offset, v); }

    public Object get(Object obj) {
        Object b = base(obj);
        if (!type.isPrimitive()) return rRef(b);
        if (type == boolean.class) return Boolean.valueOf(rBool(b));
        if (type == byte.class) return Byte.valueOf(rByte(b));
        if (type == char.class) return Character.valueOf(rChar(b));
        if (type == short.class) return Short.valueOf(rShort(b));
        if (type == int.class) return Integer.valueOf(rInt(b));
        if (type == long.class) return Long.valueOf(rLong(b));
        if (type == float.class) return Float.valueOf(rFloat(b));
        if (type == double.class) return Double.valueOf(rDouble(b));
        throw new IllegalArgumentException("void field");
    }

    public boolean getBoolean(Object obj) {
        Object b = base(obj);
        if (type == boolean.class) return rBool(b);
        throw newGetBooleanIllegalArgumentException();
    }

    public byte getByte(Object obj) {
        Object b = base(obj);
        if (type == byte.class) return rByte(b);
        throw newGetByteIllegalArgumentException();
    }

    public char getChar(Object obj) {
        Object b = base(obj);
        if (type == char.class) return rChar(b);
        throw newGetCharIllegalArgumentException();
    }

    public short getShort(Object obj) {
        Object b = base(obj);
        if (type == byte.class) return (short) rByte(b);
        if (type == short.class) return rShort(b);
        throw newGetShortIllegalArgumentException();
    }

    public int getInt(Object obj) {
        Object b = base(obj);
        if (type == byte.class) return (int) rByte(b);
        if (type == char.class) return (int) rChar(b);
        if (type == short.class) return (int) rShort(b);
        if (type == int.class) return rInt(b);
        throw newGetIntIllegalArgumentException();
    }

    public long getLong(Object obj) {
        Object b = base(obj);
        if (type == byte.class) return (long) rByte(b);
        if (type == char.class) return (long) rChar(b);
        if (type == short.class) return (long) rShort(b);
        if (type == int.class) return (long) rInt(b);
        if (type == long.class) return rLong(b);
        throw newGetLongIllegalArgumentException();
    }

    public float getFloat(Object obj) {
        Object b = base(obj);
        if (type == byte.class) return (float) rByte(b);
        if (type == char.class) return (float) rChar(b);
        if (type == short.class) return (float) rShort(b);
        if (type == int.class) return (float) rInt(b);
        if (type == long.class) return (float) rLong(b);
        if (type == float.class) return rFloat(b);
        throw newGetFloatIllegalArgumentException();
    }

    public double getDouble(Object obj) {
        Object b = base(obj);
        if (type == byte.class) return (double) rByte(b);
        if (type == char.class) return (double) rChar(b);
        if (type == short.class) return (double) rShort(b);
        if (type == int.class) return (double) rInt(b);
        if (type == long.class) return (double) rLong(b);
        if (type == float.class) return (double) rFloat(b);
        if (type == double.class) return rDouble(b);
        throw newGetDoubleIllegalArgumentException();
    }

    public void set(Object obj, Object value) throws IllegalAccessException {
        checkWrite();
        Object b = base(obj);
        if (!type.isPrimitive()) {
            if (value != null && !type.isInstance(value)) throwSetIllegalArgumentException(value);
            wRef(b, value);
            return;
        }
        if (value == null) throwSetIllegalArgumentException(value);
        if (value instanceof Boolean v) { setBoolean(obj, v); return; }
        if (value instanceof Byte v) { setByte(obj, v); return; }
        if (value instanceof Character v) { setChar(obj, v); return; }
        if (value instanceof Short v) { setShort(obj, v); return; }
        if (value instanceof Integer v) { setInt(obj, v); return; }
        if (value instanceof Long v) { setLong(obj, v); return; }
        if (value instanceof Float v) { setFloat(obj, v); return; }
        if (value instanceof Double v) { setDouble(obj, v); return; }
        throwSetIllegalArgumentException(value);
    }

    public void setBoolean(Object obj, boolean v) throws IllegalAccessException {
        checkWrite();
        Object b = base(obj);
        if (type == boolean.class) { wBool(b, v); return; }
        throwSetIllegalArgumentException(v);
    }

    public void setByte(Object obj, byte v) throws IllegalAccessException {
        checkWrite();
        Object b = base(obj);
        if (type == byte.class) { wByte(b, v); return; }
        if (type == short.class) { wShort(b, (short) v); return; }
        if (type == int.class) { wInt(b, (int) v); return; }
        if (type == long.class) { wLong(b, (long) v); return; }
        if (type == float.class) { wFloat(b, (float) v); return; }
        if (type == double.class) { wDouble(b, (double) v); return; }
        throwSetIllegalArgumentException(v);
    }

    public void setChar(Object obj, char v) throws IllegalAccessException {
        checkWrite();
        Object b = base(obj);
        if (type == char.class) { wChar(b, v); return; }
        if (type == int.class) { wInt(b, (int) v); return; }
        if (type == long.class) { wLong(b, (long) v); return; }
        if (type == float.class) { wFloat(b, (float) v); return; }
        if (type == double.class) { wDouble(b, (double) v); return; }
        throwSetIllegalArgumentException(v);
    }

    public void setShort(Object obj, short v) throws IllegalAccessException {
        checkWrite();
        Object b = base(obj);
        if (type == short.class) { wShort(b, v); return; }
        if (type == int.class) { wInt(b, (int) v); return; }
        if (type == long.class) { wLong(b, (long) v); return; }
        if (type == float.class) { wFloat(b, (float) v); return; }
        if (type == double.class) { wDouble(b, (double) v); return; }
        throwSetIllegalArgumentException(v);
    }

    public void setInt(Object obj, int v) throws IllegalAccessException {
        checkWrite();
        Object b = base(obj);
        if (type == int.class) { wInt(b, v); return; }
        if (type == long.class) { wLong(b, (long) v); return; }
        if (type == float.class) { wFloat(b, (float) v); return; }
        if (type == double.class) { wDouble(b, (double) v); return; }
        throwSetIllegalArgumentException(v);
    }

    public void setLong(Object obj, long v) throws IllegalAccessException {
        checkWrite();
        Object b = base(obj);
        if (type == long.class) { wLong(b, v); return; }
        if (type == float.class) { wFloat(b, (float) v); return; }
        if (type == double.class) { wDouble(b, (double) v); return; }
        throwSetIllegalArgumentException(v);
    }

    public void setFloat(Object obj, float v) throws IllegalAccessException {
        checkWrite();
        Object b = base(obj);
        if (type == float.class) { wFloat(b, v); return; }
        if (type == double.class) { wDouble(b, (double) v); return; }
        throwSetIllegalArgumentException(v);
    }

    public void setDouble(Object obj, double v) throws IllegalAccessException {
        checkWrite();
        Object b = base(obj);
        if (type == double.class) { wDouble(b, v); return; }
        throwSetIllegalArgumentException(v);
    }

}
